"use client";

import { useCallback, useEffect, useEffectEvent, useId, useRef, useState } from "react";
import { Popover as BasePopover } from "@base-ui/react/popover";
import { AnimatePresence, animate, motion } from "motion/react";

import { cn } from "../lib/cn";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { duration, ease, spring } from "../motion/tokens";
import { Button } from "../button/button";
import { TooltipProvider } from "../tooltip/tooltip";

import {
  type NotificationTab,
  defaultNotificationCenterLabels,
  type NotificationPanelProps,
  type NotificationCenterProps,
} from "./notification-center/model";
import { BellIcon, XIcon } from "./notification-center/icons";
import { settleNestedGlass, useNotificationList } from "./notification-center/utils";
import { PanelBody } from "./notification-center/panel-body";

export {
  type NotificationKind,
  type NotificationItem,
  type NotificationTab,
  type NotificationCenterLabels,
  defaultNotificationCenterLabels,
  // eslint-disable-next-line @typescript-eslint/no-deprecated -- deprecated alias, kept for one release
  defaultNotificationLabels,
  type NotificationPanelProps,
  type NotificationCenterProps,
} from "./notification-center/model";

/**
 * Notification center: a bell with an unread count that opens a glass inbox.
 *
 *   <NotificationCenter defaultNotifications={items} onSelect={(n) => router.push(n.href)} />
 *
 * - Tabs: All / Unread / Mentions, each grouped by day (Today, Yesterday, weekday, date),
 *   with sticky day headings and relative times that keep themselves fresh.
 * - Every row: avatar with a small "what happened" badge, the sentence, an optional quote and
 *   actions (Accept / Decline …), the time, and hover / focus actions: mark (un)read, dismiss.
 * - Touch: swipe a row left to dismiss it (a red "Dismiss" panel follows your finger; a light
 *   haptic tick when letting go would dismiss). The dismiss button stays as the
 *   single-pointer alternative. Every dismissal can be undone for a few seconds.
 * - Keyboard: Tab into the list, ↑ ↓ Home End move between notifications, Enter opens one,
 *   Delete dismisses it (focus moves to the next one), ⌘Z / Ctrl+Z undoes a dismissal,
 *   Escape closes the panel.
 * - Undo: stays up while focus is in the inbox (or the pointer is on the bar), and leaves
 *   6s after you move on. `onDismiss` fires at once (optimistic); `onRestore` when undone;
 *   `onDismissCommit` once Undo is gone for good (delete on the server there).
 * - Screen readers: the bell says "Notifications, 3 unread"; new arrivals, "all read",
 *   dismissals (with the undo shortcut) and undo are announced politely.
 * - Phones (< 40rem): the inbox docks to the bottom of the screen as a sheet over a scrim,
 *   wherever the bell is, so it always gets most of the screen.
 *
 * Motion: the glass panel itself scales and fades from the bell (a sheet slides up on phones;
 * shorter exit, no overshoot). Nested glass (tab track, avatars) drops its blur while the
 * panel fades, so no backdrop-filter ever sits inside a fading element. The bell rings and
 * the count pops when something new arrives; a dismissed row slides out and the rest glide
 * up (transforms only: rows hold glass avatars, so nothing that wraps them ever fades).
 * Reduced motion: everything changes at once; swiping still tracks the finger (that is
 * direct manipulation, not animation).
 *
 * Also exported: NotificationPanel, the same inbox as an inline glass card (for a page, a
 * drawer or a dashboard column).
 */

/* ---------- Inline panel ---------- */

/**
 * The inbox as an inline glass card (no bell): for a page, a drawer or a dashboard column.
 *
 * Props (see `NotificationPanelProps`): the shared inbox props (`notifications` / `defaultNotifications` /
 * `onNotificationsChange`, `onSelect`, `onDismiss`, `onRestore`, `onDismissCommit`, `viewAllHref`,
 * `headerActions`, `defaultTab` (`"all"`), `now`, `locale`, `labels`, `headingLevel` (`2`)) and
 * `className` (set the height; default 32rem).
 * Keyboard: Tab enters the tabs and then the list; Up, Down, Home and End move between notifications,
 * Enter opens one, Delete dismisses it (focus moves on) and Ctrl or Cmd + Z undoes a dismissal.
 * Accessibility: dismissals (with the undo shortcut), arrivals and "all read" are announced politely;
 * swipe-to-dismiss on touch always has the dismiss button as an alternative.
 * Glass and motion: one glass card (one backdrop blur); rows slide out on dismiss and the undo bar rises
 * in. Reduced motion removes the movement.
 *
 * @example
 * ```tsx
 * import { NotificationPanel, type NotificationItem } from "@sheenui/theme";
 *
 * const items: NotificationItem[] = [{ id: "1", kind: "comment", title: "Ada commented on your design", time: new Date() }];
 *
 * export function Example() {
 *   return <NotificationPanel defaultNotifications={items} className="h-[28rem]" onSelect={(n) => console.log(n.id)} />;
 * }
 * ```
 *
 * @see /blocks/notification-center
 */
export function NotificationPanel({
  notifications,
  defaultNotifications,
  onNotificationsChange,
  onSelect,
  onDismiss,
  onRestore,
  onDismissCommit,
  viewAllHref,
  headerActions,
  defaultTab = "all",
  now,
  locale,
  labels,
  headingLevel = 2,
  className,
}: NotificationPanelProps) {
  const L = { ...defaultNotificationCenterLabels, ...labels };
  const titleId = useId();
  const [items, update] = useNotificationList(notifications, defaultNotifications, onNotificationsChange);
  const [tab, setTab] = useState<NotificationTab>(defaultTab);

  return (
    <TooltipProvider delay={500}>
      <section
        role="group"
        aria-labelledby={titleId}
        data-slot="notification-panel"
        className={cn(
          "glass-2 flex h-[32rem] w-full max-w-md min-w-0 flex-col overflow-hidden rounded-sheen-xl",
          className,
        )}
      >
        <PanelBody
          items={items}
          update={update}
          tab={tab}
          onTabChange={setTab}
          onSelect={onSelect}
          onDismiss={onDismiss}
          onRestore={onRestore}
          onDismissCommit={onDismissCommit}
          viewAllHref={viewAllHref}
          headerActions={headerActions}
          now={now}
          locale={locale}
          L={L}
          titleId={titleId}
          headingLevel={headingLevel}
        />
      </section>
    </TooltipProvider>
  );
}

/* ---------- Bell + popover ---------- */

/**
 * Props (see `NotificationCenterProps`): the shared inbox props (`notifications` / `defaultNotifications`
 * / `onNotificationsChange`, `onSelect`, `onDismiss`, `onRestore`, `onDismissCommit`, `viewAllHref`,
 * `headerActions`, `defaultTab` (`"all"`), `now`, `locale`, `labels`, `headingLevel` (`2`)) plus `open` /
 * `defaultOpen` (`false`) / `onOpenChange`, `side` (`"bottom"`), `align` (`"end"`), `max` (`99`),
 * `className` (the bell) and `panelClassName`.
 * Keyboard: the bell is a button (Enter or Space opens the panel, Escape closes it and returns focus);
 * inside, the same keys as `NotificationPanel` apply.
 * Accessibility: the bell is named "Notifications, 3 unread" and the count is text; the panel is a
 * labelled popover.
 * Glass and motion: the bell rings when something new arrives (not under reduced motion); the panel is
 * one portaled glass card.
 *
 * @example
 * ```tsx
 * import { NotificationCenter, type NotificationItem } from "@sheenui/theme";
 *
 * const items: NotificationItem[] = [{ id: "1", kind: "mention", title: "Grace mentioned you", time: new Date() }];
 *
 * export function Example() {
 *   return <NotificationCenter defaultNotifications={items} onSelect={(n) => window.location.assign(`/inbox/${n.id}`)} />;
 * }
 * ```
 *
 * @see /blocks/notification-center
 */
export function NotificationCenter({
  notifications,
  defaultNotifications,
  onNotificationsChange,
  onSelect,
  onDismiss,
  onRestore,
  onDismissCommit,
  viewAllHref,
  headerActions,
  defaultTab = "all",
  now,
  locale,
  labels,
  headingLevel = 2,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  side = "bottom",
  align = "end",
  max = 99,
  className,
  panelClassName,
}: NotificationCenterProps) {
  const L = { ...defaultNotificationCenterLabels, ...labels };
  const reduced = useSheenReducedMotion();
  const titleId = useId();
  const [items, update] = useNotificationList(notifications, defaultNotifications, onNotificationsChange);
  const [tab, setTab] = useState<NotificationTab>(defaultTab);
  const [innerOpen, setInnerOpen] = useState(defaultOpen);
  const open = openProp ?? innerOpen;
  const popupRef = useRef<HTMLDivElement | null>(null);
  const bellRef = useRef<HTMLSpanElement>(null);
  // What the person has already seen in the panel; what arrives while it is closed glows on the next open.
  const [seen] = useState(() => new Set(items.map((i) => i.id)));

  const unread = items.filter((i) => !i.read).length;
  const count = unread > max ? `${max}+` : String(unread);

  const setOpen = useCallback(
    (next: boolean) => {
      // Closing: the panel fades out, so its nested glass drops its blur first.
      if (!next) settleNestedGlass(popupRef.current, true);
      if (openProp === undefined) setInnerOpen(next);
      onOpenChange?.(next);
    },
    [openProp, onOpenChange],
  );

  // Opening: the popup mounts with its nested glass unblurred (this runs before its first
  // frame, with the whole subtree in place); onOpenChangeComplete restores it once the fade is done.
  const popupCallbackRef = useCallback((node: HTMLDivElement | null) => {
    popupRef.current = node;
    if (node) settleNestedGlass(node, true);
  }, []);

  // Something new arrived: ring the bell and tell screen readers (not on first render).
  // Every id ever listed is remembered, so a notification brought back by Undo is not "new".
  const [announcement, setAnnouncement] = useState("");
  const known = useRef<Set<string> | null>(null);
  known.current ??= new Set(items.map((i) => i.id));
  // The wording is read when new items arrive: labels are rebuilt each render and must not re-run this.
  const announceNew = useEffectEvent((count: number) => setAnnouncement(L.announceNew(count)));
  useEffect(() => {
    const ids = known.current;
    if (!ids) return;
    const arrived = items.filter((i) => !ids.has(i.id) && !i.read).length;
    for (const item of items) ids.add(item.id);
    if (arrived === 0) return;
    announceNew(arrived);
    if (!reduced && bellRef.current) {
      animate(
        bellRef.current,
        { rotate: [0, 18, -14, 10, -6, 3, 0] },
        { duration: duration.slower * 1.3, ease: ease.inOut },
      );
    }
  }, [items, reduced]);

  return (
    <BasePopover.Root
      open={open}
      onOpenChange={setOpen}
      onOpenChangeComplete={(isOpen) => {
        if (isOpen) settleNestedGlass(popupRef.current, false);
      }}
    >
      <BasePopover.Trigger
        render={<Button variant="glass" size="icon" />}
        aria-label={L.trigger(unread)}
        className={cn("relative data-popup-open:bg-sheen-accent-soft data-popup-open:text-sheen-accent", className)}
      >
        <span ref={bellRef} className="flex origin-[50%_10%]">
          <BellIcon className="size-5" />
        </span>
        <AnimatePresence initial={false}>
          {unread > 0 && (
            <motion.span
              key="badge"
              aria-hidden
              initial={reduced ? false : { scale: 0 }}
              animate={{ scale: 1, transition: reduced ? { duration: 0 } : spring.bouncy }}
              exit={{ scale: 0, transition: { duration: reduced ? 0 : duration.exit, ease: ease.exit } }}
              className={cn(
                "sheen-fill pointer-events-none absolute -top-1.5 -end-1.5 flex h-5 min-w-5 items-center justify-center rounded-sheen-full px-1.5",
                "text-2xs font-semibold text-sheen-accent-fg tabular-nums [background-image:var(--sheen-accent-fill)]",
                "shadow-[0_0_0_2px_var(--sheen-bg),0_4px_12px_-4px_var(--sheen-accent-glow)]",
                "forced-colors:border forced-colors:border-[CanvasText]",
              )}
            >
              {/* The number pops on change. */}
              <motion.span
                key={count}
                initial={reduced ? false : { scale: 0.5 }}
                animate={{ scale: 1 }}
                transition={spring.bouncy}
              >
                {count}
              </motion.span>
            </motion.span>
          )}
        </AnimatePresence>
      </BasePopover.Trigger>
      {/* Outside the button: a live region inside a named button is not reliably read. */}
      <span role="status" className="sr-only">
        {announcement}
      </span>

      <BasePopover.Portal>
        {/* Phones: the sheet sits over a scrim; tapping it closes the inbox. */}
        <BasePopover.Backdrop
          className={cn(
            "fixed inset-0 z-50 hidden bg-sheen-scrim max-sm:block",
            "transition-opacity duration-(--sheen-duration-base) ease-sheen-out data-starting-style:opacity-0",
            "data-ending-style:opacity-0 data-ending-style:duration-(--sheen-duration-exit) data-ending-style:ease-sheen-exit",
          )}
        />
        <BasePopover.Positioner
          side={side}
          align={align}
          sideOffset={10}
          collisionPadding={8}
          className={cn(
            "z-50",
            // Phones: dock to the bottom of the screen as a sheet, wherever the bell happens to be.
            "max-sm:fixed! max-sm:inset-x-0! max-sm:top-auto! max-sm:bottom-0! max-sm:transform-none!",
          )}
        >
          <BasePopover.Popup
            ref={popupCallbackRef}
            aria-labelledby={titleId}
            data-slot="notification-center"
            // Keyboard: land on the active tab (not on "Mark all as read", one Enter away from a bulk action).
            initialFocus={(type) => {
              if (type === "touch") return true;
              return popupRef.current?.querySelector<HTMLElement>("[role='tab'][aria-selected='true']") ?? true;
            }}
            className={cn(
              "glass-3 flex flex-col overflow-hidden rounded-sheen-xl outline-none",
              "[transition:opacity_var(--sheen-duration-fast)_var(--sheen-ease-out),scale_var(--sheen-duration-snappy)_var(--sheen-ease-snappy),translate_var(--sheen-duration-snappy)_var(--sheen-ease-snappy)]",
              "data-starting-style:opacity-0 data-ending-style:opacity-0",
              "data-ending-style:[transition:opacity_var(--sheen-duration-exit)_var(--sheen-ease-exit),scale_var(--sheen-duration-exit)_var(--sheen-ease-exit),translate_var(--sheen-duration-exit)_var(--sheen-ease-exit)]",
              // From the bell: grows out of it, settles with a spring.
              "sm:h-[min(34rem,var(--available-height))] sm:w-[min(25rem,calc(100vw-1rem))] sm:origin-(--transform-origin)",
              "motion-ok:sm:data-starting-style:scale-[0.96] motion-ok:sm:data-ending-style:scale-[0.98]",
              // Phones: a bottom sheet that slides up (no overshoot, so no gap ever opens under it).
              "max-sm:h-[min(42rem,calc(100dvh-3.5rem))] max-sm:w-full max-sm:rounded-b-none max-sm:border-b-0 max-sm:pb-[env(safe-area-inset-bottom)]",
              "motion-ok:max-sm:data-starting-style:translate-y-16 motion-ok:max-sm:data-ending-style:translate-y-10",
              panelClassName,
            )}
          >
            <TooltipProvider delay={500}>
              <PanelBody
                items={items}
                update={update}
                tab={tab}
                onTabChange={setTab}
                onSelect={onSelect}
                onDismiss={onDismiss}
                onRestore={onRestore}
                onDismissCommit={onDismissCommit}
                onClose={() => setOpen(false)}
                seen={seen}
                viewAllHref={viewAllHref}
                headerActions={headerActions}
                closeButton={
                  // Phones only: a sheet needs a visible way out (Escape and the scrim work too).
                  <BasePopover.Close
                    render={<Button variant="ghost" size="icon" aria-label={L.close} />}
                    className="size-8 text-sheen-fg-muted hover:text-sheen-fg sm:hidden"
                  >
                    <XIcon />
                  </BasePopover.Close>
                }
                now={now}
                locale={locale}
                L={L}
                titleId={titleId}
                headingLevel={headingLevel}
              />
            </TooltipProvider>
          </BasePopover.Popup>
        </BasePopover.Positioner>
      </BasePopover.Portal>
    </BasePopover.Root>
  );
}

import { type ComponentProps, type ReactNode } from "react";

import { cn } from "../../lib/cn";
import { type NotificationKind } from "./model";

/* ---------- Icons (decorative, 24×24, currentColor) ---------- */

/** The shared 24px stroke SVG frame of the notification icons. @internal */
export function Icon({ children, className, ...props }: ComponentProps<"svg">) {
  return (
    <svg
      aria-hidden
      focusable="false"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={cn("size-4", className)}
      {...props}
    >
      {children}
    </svg>
  );
}

/** The bell icon of the trigger. @internal */
export const BellIcon = (p: ComponentProps<"svg">) => (
  <Icon {...p}>
    <path d="M6 8.5a6 6 0 0 1 12 0c0 6 2.5 7.5 2.5 7.5h-17S6 14.5 6 8.5Z" />
    <path d="M10.3 20a1.9 1.9 0 0 0 3.4 0" />
  </Icon>
);
/** The double-check icon of the mark-all-read action. @internal */
export const CheckAllIcon = (p: ComponentProps<"svg">) => (
  <Icon {...p}>
    <path d="M2.5 12.5 7 17l9.5-10" />
    <path d="m12 16 1 1 9.5-10" />
  </Icon>
);
/** The check icon of the mark-read action. @internal */
export const CheckIcon = (p: ComponentProps<"svg">) => (
  <Icon {...p}>
    <path d="M5 12.5l4.5 4.5L19 7.5" />
  </Icon>
);
/** The dot icon of the unread marker. @internal */
export const DotIcon = (p: ComponentProps<"svg">) => (
  <Icon {...p}>
    <circle cx="12" cy="12" r="4.5" />
  </Icon>
);
/** The close icon. @internal */
export const XIcon = (p: ComponentProps<"svg">) => (
  <Icon {...p}>
    <path d="M6 6l12 12M18 6 6 18" />
  </Icon>
);
/** The trash icon of the dismiss action. @internal */
export const TrashIcon = (p: ComponentProps<"svg">) => (
  <Icon {...p}>
    <path d="M4 7h16M10 11v6M14 11v6M6 7l1 12a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2l1-12M9 7V4h6v3" />
  </Icon>
);
/** The right arrow icon of a notification link. @internal */
export const ArrowRightIcon = ({ className, ...p }: ComponentProps<"svg">) => (
  <Icon {...p} className={cn("rtl:-scale-x-100", className)}>
    <path d="M5 12h14M13 6l6 6-6 6" />
  </Icon>
);
/** The inbox icon of the empty state. @internal */
export const InboxIcon = (p: ComponentProps<"svg">) => (
  <Icon {...p}>
    <path d="M3 13h5l1.5 3h5L16 13h5" />
    <path d="M5.5 5h13L21 13v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-5l2.5-8Z" />
  </Icon>
);
/** The sparkle-check icon of the all-caught-up state. @internal */
export const SparkleCheckIcon = (p: ComponentProps<"svg">) => (
  <Icon {...p}>
    <circle cx="12" cy="12" r="9" />
    <path d="m8 12.5 2.8 2.8L16.5 9.5" />
  </Icon>
);

/** The avatar icon of each notification kind. @internal */
export const kindIcons: Record<NotificationKind, ReactNode> = {
  mention: (
    <>
      <circle cx="12" cy="12" r="3.5" />
      <path d="M15.5 12v1.5a2.5 2.5 0 0 0 5 0V12a8.5 8.5 0 1 0-3.4 6.8" />
    </>
  ),
  comment: <path d="M20 11.5a7.5 7.5 0 0 1-11 6.6L4 19.5l1.4-4.6A7.5 7.5 0 1 1 20 11.5Z" />,
  reaction: <path d="M12 20s-7.5-4.4-7.5-10A4.3 4.3 0 0 1 12 7.4 4.3 4.3 0 0 1 19.5 10c0 5.6-7.5 10-7.5 10Z" />,
  invite: (
    <>
      <circle cx="9.5" cy="8" r="3.5" />
      <path d="M3 20c.5-3.6 3.1-5.5 6.5-5.5s6 1.9 6.5 5.5M19 8v6M16 11h6" />
    </>
  ),
  assign: (
    <>
      <rect x="4" y="4" width="16" height="16" rx="4" />
      <path d="m8.5 12.5 2.5 2.5 4.5-5" />
    </>
  ),
  system: (
    <>
      <circle cx="12" cy="12" r="9" />
      <path d="M12 11v5M12 7.5h.01" />
    </>
  ),
  success: (
    <>
      <circle cx="12" cy="12" r="9" />
      <path d="m8.5 12.5 2.5 2.5 4.5-5" />
    </>
  ),
  warning: (
    <>
      <path d="M10.3 3.9 2 18a2 2 0 0 0 1.7 3h16.6a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z" />
      <path d="M12 9.5v4M12 17h.01" />
    </>
  ),
};

/* Tinted over a near-opaque surface (like Badge), so the *-text icon colours keep their contrast. */
/** The classes that tint a surface with the `--tint` variable while keeping icon contrast. @internal */
export const tinted = "bg-sheen-surface [background-image:linear-gradient(var(--tint),var(--tint))]";
/** The tint classes of each notification kind. @internal */
export const kindTone: Record<NotificationKind, string> = {
  mention: `${tinted} [--tint:var(--sheen-accent-soft)] text-sheen-accent`,
  comment: `${tinted} [--tint:var(--sheen-accent-soft)] text-sheen-accent`,
  reaction: `${tinted} [--tint:var(--sheen-danger-soft)] text-sheen-danger-text`,
  invite: `${tinted} [--tint:var(--sheen-success-soft)] text-sheen-success-text`,
  assign: `${tinted} [--tint:var(--sheen-warning-soft)] text-sheen-warning-text`,
  system: `${tinted} [--tint:var(--sheen-hover)] text-sheen-fg-muted`,
  success: `${tinted} [--tint:var(--sheen-success-soft)] text-sheen-success-text`,
  warning: `${tinted} [--tint:var(--sheen-warning-soft)] text-sheen-warning-text`,
};

import type { HeadingLevelOption } from "../../lib/heading";
import { type ReactNode } from "react";

/* ---------- Types ---------- */

/** What a notification is about; it picks the small badge on the avatar (or the large icon of a system notice). */
export type NotificationKind =
  "mention" | "comment" | "reaction" | "invite" | "assign" | "system" | "success" | "warning";

/** One notification: id, optional actor, kind, title (also the row's accessible name), description, time, read state, mention flag, link and extra action buttons. */
export type NotificationItem = {
  id: string;
  /** Who did it, shown as an avatar (initials when there is no image). Leave out for system notices. */
  actor?: { name: string; avatar?: string };
  /** What happened: a small badge on the avatar (or the large icon of a system notice). */
  kind?: NotificationKind;
  /** The sentence, e.g. <><b>Ada</b> mentioned you in <b>Q3 plan</b></>. It is also the row's accessible name. */
  title: ReactNode;
  /** Optional second line: a quote, a file name… Clamped to two lines. */
  description?: ReactNode;
  /** When it happened (Date, ISO string or epoch ms). An unparsable value is listed last, under "Undated". */
  time: Date | string | number;
  read?: boolean;
  /** Whether the notification is listed under the Mentions tab. Defaults to kind === "mention". */
  mention?: boolean;
  /** Opening the notification follows this link. */
  href?: string;
  /** Extra buttons under the text, e.g. Accept / Decline an invite. */
  actions?: ReactNode;
};

/** A tab of the notification inbox: all, unread or mentions. */
export type NotificationTab = "all" | "unread" | "mentions";

/** Every user-facing string (i18n). */
export type NotificationCenterLabels = {
  /** Accessible name of the bell button. */
  trigger: (unread: number) => string;
  title: string;
  markAllRead: string;
  /** Close button of the phone sheet. */
  close: string;
  /** Name of the tab list. */
  tabs: string;
  all: string;
  unread: string;
  mentions: string;
  today: string;
  yesterday: string;
  /** Day heading for notifications whose `time` can't be read. */
  undated: string;
  justNow: string;
  /** Read after an unread notification's text. */
  unreadState: string;
  markRead: string;
  markUnread: string;
  dismiss: string;
  /** Shown behind a row while it is swiped. */
  swipeDismiss: string;
  dismissed: string;
  undo: string;
  viewAll: string;
  emptyAllTitle: string;
  emptyAllDescription: string;
  emptyUnreadTitle: string;
  emptyUnreadDescription: string;
  emptyMentionsTitle: string;
  emptyMentionsDescription: string;
  /** Announced when new notifications arrive. */
  announceNew: (count: number) => string;
  announceAllRead: string;
  /** Announced after a dismissal; receives the spoken undo shortcut ("Command Z" / "Control Z"). */
  announceDismissed: (undoShortcut: string) => string;
  announceRestored: string;
};

/** The English `NotificationCenterLabels` used when `labels` is omitted; a partial `labels` prop is merged over them. */
export const defaultNotificationCenterLabels: NotificationCenterLabels = {
  trigger: (n) => (n > 0 ? `Notifications, ${n} unread` : "Notifications"),
  title: "Notifications",
  markAllRead: "Mark all as read",
  close: "Close notifications",
  tabs: "Filter notifications",
  all: "All",
  unread: "Unread",
  mentions: "Mentions",
  today: "Today",
  yesterday: "Yesterday",
  undated: "Undated",
  justNow: "Just now",
  unreadState: "unread",
  markRead: "Mark as read",
  markUnread: "Mark as unread",
  dismiss: "Dismiss",
  swipeDismiss: "Dismiss",
  dismissed: "Notification dismissed",
  undo: "Undo",
  viewAll: "View all notifications",
  emptyAllTitle: "No notifications yet",
  emptyAllDescription: "When teammates mention you, comment or invite you, it shows up here.",
  emptyUnreadTitle: "You're all caught up",
  emptyUnreadDescription: "Nothing new since you last looked. Enjoy the quiet.",
  emptyMentionsTitle: "No mentions",
  emptyMentionsDescription: "When someone @mentions you, you'll find it here.",
  announceNew: (n) => (n === 1 ? "1 new notification" : `${n} new notifications`),
  announceAllRead: "All notifications marked as read",
  announceDismissed: (shortcut) => `Notification dismissed. Press ${shortcut} to undo.`,
  announceRestored: "Notification restored",
};

/**
 * The former name of `defaultNotificationCenterLabels`, kept as an alias for one release.
 *
 * @deprecated Renamed `defaultNotificationCenterLabels`; this alias is removed after one release.
 */
export const defaultNotificationLabels = defaultNotificationCenterLabels;

/** Props shared by `NotificationCenter` (bell + popover) and `NotificationPanel` (inline card). */
export type SharedProps = {
  /** The notifications to show, when you control the list yourself (pair it with the change callbacks). */
  notifications?: NotificationItem[];
  /** Sets the starting list when uncontrolled. */
  defaultNotifications?: NotificationItem[];
  /** Called with the whole new list after any change (read, unread, dismiss, undo). */
  onNotificationsChange?: (next: NotificationItem[]) => void;
  /** Called when a notification is opened (it is marked as read first). */
  onSelect?: (item: NotificationItem) => void;
  /** Called as soon as a notification is dismissed (button, Delete key or swipe). Undo can still bring it back: see onRestore. */
  onDismiss?: (item: NotificationItem) => void;
  /** Called when Undo brings a dismissed notification back. */
  onRestore?: (item: NotificationItem) => void;
  /**
   * Called once a dismissal can no longer be undone: the undo bar timed out, another
   * notification was dismissed, or the inbox closed. Delete it on your server here.
   */
  onDismissCommit?: (item: NotificationItem) => void;
  /** Shows a "View all notifications" link at the bottom. */
  viewAllHref?: string;
  /** Extra controls in the header, after "Mark all as read" (e.g. a settings link). */
  headerActions?: ReactNode;
  /** The tab that is selected when the panel first renders. */
  defaultTab?: NotificationTab;
  /**
   * The current time for "5m ago" and the day groups. Default: the real clock, refreshed every
   * 30 seconds. On a prerendered or server-rendered page pass a fixed date, so the HTML matches
   * what the browser renders when it hydrates.
   */
  now?: Date;
  /** Sets the BCP 47 locale for day headings and times. Default: the browser's; pass one on prerendered pages. */
  locale?: string;
  /** Any UI string (i18n). */
  labels?: Partial<NotificationCenterLabels>;
  /** Heading level of the panel title (`2 | 3 | 4`, default 2); day groups sit one level below. `"none"` renders paragraphs with no heading role (for an example). */
  headingLevel?: HeadingLevelOption;
};

/** Props of `NotificationPanel`: the shared inbox props plus `className`. */
export type NotificationPanelProps = SharedProps & {
  /** Classes for the glass card (set its height here; it defaults to 32rem). */
  className?: string;
};

/** Props of `NotificationCenter`: the shared inbox props plus the popover ones below. */
export type NotificationCenterProps = SharedProps & {
  /** Whether the panel is open (controlled). */
  open?: boolean;
  /** Whether the panel is open at first when `open` is not controlled (`boolean`, default `false`). */
  defaultOpen?: boolean;
  /** Called when the panel opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** Which side of the bell the panel opens on (`"top" | "bottom" | "left" | "right"`, default `"bottom"`). */
  side?: "top" | "bottom" | "left" | "right";
  /** Sets the alignment against the bell (`"start" | "center" | "end"`, default `"end"`). */
  align?: "start" | "center" | "end";
  /** Counts above this show as "99+" (`number`, default 99). */
  max?: number;
  /** Classes for the bell button (the outer element; the panel is portaled). */
  className?: string;
  /** Adds extra classes to the glass panel. */
  panelClassName?: string;
};

"use client";

import { useCallback, useEffect, useId, useMemo, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { useLatest } from "../../hooks/use-latest";
import { AnimatePresence } from "motion/react";

import { cn } from "../../lib/cn";
import { HEADING_TAGS, headingBelow, type HeadingTag, type HeadingLevelOption } from "../../lib/heading";
import { Button } from "../../button/button";
import { EmptyState } from "../../empty-state/empty-state";
import { useShortcutPlatform } from "../../kbd/kbd";
import { formatShortcut, matchesShortcut, toAriaKeyShortcuts } from "../../kbd/shortcut";
import { Tabs, TabsList, TabsPanel, TabsTab } from "../../tabs/tabs";
import { type NotificationItem, type NotificationTab, type NotificationCenterLabels } from "./model";
import { Icon, CheckAllIcon, ArrowRightIcon, InboxIcon, SparkleCheckIcon, kindIcons } from "./icons";
import { toDate, byNewest, useFormatters, groupLabel, timeLabel, useNow, type Update, isMention } from "./utils";
import { NotificationRow, UndoBar } from "./row";

/* ---------- Panel body (shared by the popover and the inline card) ---------- */

/** The props of the notification panel body. @internal */
export type BodyProps = {
  items: NotificationItem[];
  update: Update;
  tab: NotificationTab;
  onTabChange: (tab: NotificationTab) => void;
  onSelect?: (item: NotificationItem) => void;
  onDismiss?: (item: NotificationItem) => void;
  onRestore?: (item: NotificationItem) => void;
  onDismissCommit?: (item: NotificationItem) => void;
  /** Close the surrounding popover after a notification is opened. */
  onClose?: () => void;
  viewAllHref?: string;
  headerActions?: ReactNode;
  /** Shown last in the header, e.g. the phone sheet's close button. */
  closeButton?: ReactNode;
  now?: Date;
  locale?: string;
  L: NotificationCenterLabels;
  titleId: string;
  headingLevel: HeadingLevelOption;
  /** Ids already shown. The popover keeps this across openings, so arrivals while it was closed glow once. */
  seen?: Set<string>;
};

/** A dismissed notification and its original index, kept so undo can restore it. @internal */
export type Dismissed = { item: NotificationItem; index: number };

/** The filter tabs of the panel, in display order. @internal */
export const TABS: NotificationTab[] = ["all", "unread", "mentions"];

/** How long the undo bar stays once the person has moved on (focus and pointer elsewhere). */
export const UNDO_MS = 6000;

/** The panel body: tabs, grouped list, empty state and undo bar. @internal */
export function PanelBody({
  items,
  update,
  tab,
  onTabChange,
  onSelect,
  onDismiss,
  onRestore,
  onDismissCommit,
  onClose,
  viewAllHref,
  headerActions,
  closeButton,
  now: nowProp,
  locale,
  L,
  titleId,
  headingLevel,
  seen: seenProp,
}: BodyProps) {
  const Heading = HEADING_TAGS[headingBelow(headingLevel, 0)];
  const GroupHeading = HEADING_TAGS[headingBelow(headingLevel, 1)];
  const now = useNow(nowProp);
  const f = useFormatters(locale);
  const platform = useShortcutPlatform();
  const bodyRef = useRef<HTMLDivElement>(null);
  const pendingFocus = useRef<string | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const [dismissed, setDismissed] = useState<Dismissed | null>(null);
  // Read while the Unread tab is open: kept in place until the tab changes, so rows don't jump away under the pointer.
  const [kept, setKept] = useState<ReadonlySet<string>>(() => new Set());
  // Rows not shown before (they arrived since) glow once.
  const [ownSeen] = useState(() => new Set(items.map((i) => i.id)));
  const seen = seenProp ?? ownSeen;

  // Parse every time once per list (null = unreadable).
  const dates = useMemo(() => new Map(items.map((i) => [i.id, toDate(i.time)])), [items]);
  const sorted = useMemo(() => [...items].sort(byNewest(dates)), [items, dates]);
  const unreadCount = items.filter((i) => !i.read).length;
  const unreadMentions = items.filter((i) => isMention(i) && !i.read).length;
  const lists: Record<NotificationTab, NotificationItem[]> = {
    all: sorted,
    unread: sorted.filter((i) => !i.read || kept.has(i.id)),
    mentions: sorted.filter(isMention),
  };
  const undoShortcut = formatShortcut("mod+z", platform);

  const announce = (text: string) => {
    // Clear first so the same message twice is still read out.
    setAnnouncement("");
    requestAnimationFrame(() => setAnnouncement(text));
  };

  // Move focus after a dismissal or undo, once the list has re-rendered.
  useEffect(() => {
    const target = pendingFocus.current;
    if (!target) return;
    pendingFocus.current = null;
    const root = bodyRef.current;
    const el =
      target === "#tab"
        ? root?.querySelector<HTMLElement>("[role='tab'][aria-selected='true']")
        : root?.querySelector<HTMLElement>(
            `[data-notification-id="${CSS.escape(target)}"] [data-slot="notification-main"]`,
          );
    el?.focus();
  }, [items]);

  /* ----- Undo window ----- */

  // The dismissal Undo can still revert. It is committed (onDismissCommit) when the window closes.
  const pendingCommit = useRef<NotificationItem | null>(null);
  const commitRef = useLatest(onDismissCommit);
  const commitPending = useCallback(() => {
    const item = pendingCommit.current;
    pendingCommit.current = null;
    if (item) commitRef.current?.(item);
  }, [commitRef]);
  // Closing the inbox (unmount) makes the last dismissal final.
  useEffect(() => commitPending, [commitPending]);

  // The bar waits while focus is anywhere in the inbox or the pointer is on the bar, so
  // keyboard and screen reader users get all the time they need; 6s after they move on, it goes.
  const [focusInside, setFocusInside] = useState(false);
  const [barHovered, setBarHovered] = useState(false);
  useEffect(() => {
    if (!dismissed || focusInside || barHovered) return;
    const timer = window.setTimeout(() => {
      setDismissed(null);
      commitPending();
    }, UNDO_MS);
    return () => window.clearTimeout(timer);
  }, [dismissed, focusInside, barHovered, commitPending]);

  function changeTab(next: NotificationTab) {
    setKept(new Set());
    onTabChange(next);
  }

  function setRead(item: NotificationItem, read: boolean) {
    if (read && tab === "unread") setKept((k) => new Set(k).add(item.id));
    update((prev) => prev.map((i) => (i.id === item.id ? { ...i, read } : i)));
  }

  function markAllRead() {
    // Nothing left to mark: the button stays focusable (aria-disabled) so focus never drops to <body>.
    if (unreadCount === 0) return;
    setKept(new Set());
    update((prev) => prev.map((i) => (i.read ? i : { ...i, read: true })));
    announce(L.announceAllRead);
  }

  function dismiss(item: NotificationItem, moveFocus: boolean) {
    if (moveFocus) {
      const visible = lists[tab];
      const at = visible.findIndex((i) => i.id === item.id);
      const neighbour = visible[at + 1] ?? visible[at - 1];
      pendingFocus.current = neighbour ? neighbour.id : "#tab";
    }
    // Only the latest dismissal can be undone: the one before it is final now.
    commitPending();
    pendingCommit.current = item;
    const index = items.findIndex((i) => i.id === item.id);
    update((prev) => prev.filter((i) => i.id !== item.id));
    setDismissed({ item, index });
    announce(L.announceDismissed(undoShortcut.spoken));
    onDismiss?.(item);
  }

  function undo() {
    if (!dismissed) return;
    const { item, index } = dismissed;
    pendingCommit.current = null;
    update((prev) => {
      if (prev.some((i) => i.id === item.id)) return prev;
      const next = [...prev];
      next.splice(Math.min(Math.max(index, 0), next.length), 0, item);
      return next;
    });
    pendingFocus.current = item.id;
    setDismissed(null);
    setBarHovered(false);
    announce(L.announceRestored);
    onRestore?.(item);
  }

  function select(item: NotificationItem) {
    if (!item.read) setRead(item, true);
    onSelect?.(item);
    onClose?.();
  }

  /* ⌘Z / Ctrl+Z anywhere in the inbox brings the last dismissal back (there is no text to edit here). */
  function onBodyKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (dismissed && matchesShortcut(event, "mod+z", platform)) {
      event.preventDefault();
      undo();
    }
  }

  /* ↑ ↓ Home End between rows, Delete to dismiss. */
  function onListKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const target = event.target as HTMLElement;
    if (target.dataset.slot !== "notification-main") return;
    const mains = Array.from(
      event.currentTarget.querySelectorAll<HTMLElement>("[data-slot='notification-main']"),
    ).filter((el) => !el.closest("[inert]"));
    const at = mains.indexOf(target);
    let next: HTMLElement | undefined;
    switch (event.key) {
      case "ArrowDown":
        next = mains[Math.min(at + 1, mains.length - 1)];
        break;
      case "ArrowUp":
        next = mains[Math.max(at - 1, 0)];
        break;
      case "Home":
        next = mains[0];
        break;
      case "End":
        next = mains[mains.length - 1];
        break;
      case "Delete":
      case "Backspace": {
        const id = target.closest<HTMLElement>("[data-notification-id]")?.dataset.notificationId;
        const item = items.find((i) => i.id === id);
        if (item) {
          event.preventDefault();
          dismiss(item, true);
        }
        return;
      }
      default:
        return;
    }
    event.preventDefault();
    if (!next) return;
    next.focus({ preventScroll: true });
    // Bring the whole row (and its row-wide focus ring) into view, clear of the sticky day heading.
    next.closest("li")?.scrollIntoView({ block: "nearest" });
  }

  const empty: Record<
    NotificationTab,
    { icon: ReactNode; title: string; description: string; tone: "accent" | "success" | "neutral" }
  > = {
    all: {
      icon: <InboxIcon className="size-6" />,
      title: L.emptyAllTitle,
      description: L.emptyAllDescription,
      tone: "neutral",
    },
    unread: {
      icon: <SparkleCheckIcon className="size-6" />,
      title: L.emptyUnreadTitle,
      description: L.emptyUnreadDescription,
      tone: "success",
    },
    mentions: {
      icon: <Icon className="size-6">{kindIcons.mention}</Icon>,
      title: L.emptyMentionsTitle,
      description: L.emptyMentionsDescription,
      tone: "accent",
    },
  };

  return (
    <div
      ref={bodyRef}
      // Delegates the inbox's keyboard shortcuts from its focusable children; the wrapper has no role of its own.
      role="presentation"
      data-undo={dismissed ? "" : undefined}
      onKeyDown={onBodyKeyDown}
      onFocus={() => setFocusInside(true)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setFocusInside(false);
      }}
      className="group/inbox relative flex min-h-0 flex-1 flex-col"
    >
      <div className="flex items-center justify-between gap-2 px-4 pt-4 pb-3">
        <Heading id={titleId} className="min-w-0 truncate text-base font-semibold tracking-tight">
          {L.title}
        </Heading>
        <div className="-me-1.5 flex shrink-0 items-center gap-1">
          <Button
            variant="ghost"
            size="sm"
            // aria-disabled, not disabled: pressing it moves nothing, and focus stays on it.
            aria-disabled={unreadCount === 0 || undefined}
            data-unavailable={unreadCount === 0 ? "" : undefined}
            onClick={markAllRead}
            leading={<CheckAllIcon />}
            className="text-sheen-accent data-unavailable:pointer-events-none data-unavailable:opacity-55"
          >
            {L.markAllRead}
          </Button>
          {headerActions}
          {closeButton}
        </div>
      </div>

      <Tabs value={tab} onValueChange={(value) => changeTab(value as NotificationTab)} className="min-h-0 flex-1 gap-0">
        <div className="px-4 pb-3">
          <TabsList aria-label={L.tabs}>
            {TABS.map((t) => {
              const count = t === "unread" ? unreadCount : t === "mentions" ? unreadMentions : 0;
              return (
                <TabsTab key={t} value={t} className="min-w-11 px-3">
                  {L[t]}
                  {count > 0 && (
                    // Tint over a near-opaque surface: accent text keeps AA on the glass track and on the active pill.
                    <span className="flex h-[1.125rem] min-w-[1.125rem] items-center justify-center rounded-sheen-full bg-sheen-surface/90 [background-image:linear-gradient(var(--sheen-accent-soft),var(--sheen-accent-soft))] px-1 text-2xs font-semibold text-sheen-accent tabular-nums forced-colors:border forced-colors:border-[CanvasText]">
                      {count}
                    </span>
                  )}
                </TabsTab>
              );
            })}
          </TabsList>
        </div>
        <div aria-hidden className="h-px shrink-0 bg-sheen-border" />

        {TABS.map((t) => {
          const list = lists[t];
          const groups: { label: string; items: NotificationItem[] }[] = [];
          for (const item of list) {
            const label = groupLabel(dates.get(item.id) ?? null, now, f, L);
            const last = groups[groups.length - 1];
            if (last?.label === label) last.items.push(item);
            else groups.push({ label, items: [item] });
          }
          return (
            <TabsPanel
              key={t}
              value={t}
              onKeyDown={onListKeyDown}
              // With rows to focus, the panel itself needn't be a tab stop (it stays one when empty).
              tabIndex={list.length > 0 ? -1 : 0}
              className={cn(
                "relative min-h-0 flex-1 overflow-y-auto overscroll-contain rounded-none [scrollbar-width:thin] focus-visible:-outline-offset-2",
                // While the undo bar floats over the bottom, the last row can still scroll clear of it.
                "group-data-undo/inbox:pb-16",
              )}
            >
              {list.length === 0 ? (
                <EmptyState
                  role="status"
                  icon={empty[t].icon}
                  title={empty[t].title}
                  description={empty[t].description}
                  tone={empty[t].tone}
                  headingLevel={false}
                  className="h-full min-h-56 px-6 py-8"
                />
              ) : (
                groups.map((group) => (
                  <DayGroup key={group.label} label={group.label} Heading={GroupHeading}>
                    <AnimatePresence initial={false}>
                      {group.items.map((item) => {
                        const date = dates.get(item.id) ?? null;
                        return (
                          <NotificationRow
                            key={item.id}
                            item={item}
                            fresh={!seen.has(item.id)}
                            onSeen={() => seen.add(item.id)}
                            time={date ? timeLabel(date, now, f, L) : null}
                            fullTime={date ? f.full.format(date) : undefined}
                            dateTime={date?.toISOString()}
                            L={L}
                            onSelect={select}
                            onToggleRead={(read) => setRead(item, read)}
                            onDismiss={dismiss}
                          />
                        );
                      })}
                    </AnimatePresence>
                  </DayGroup>
                ))
              )}
            </TabsPanel>
          );
        })}
      </Tabs>

      {viewAllHref && (
        <div className="shrink-0 border-t border-sheen-border p-2">
          <Button
            variant="ghost"
            fullWidth
            // eslint-disable-next-line jsx-a11y/anchor-has-content -- Button injects its children (the label) into the anchor given to `render`
            render={<a href={viewAllHref} />}
            trailing={<ArrowRightIcon />}
            className="text-sheen-accent"
          >
            {L.viewAll}
          </Button>
        </div>
      )}

      <UndoBar
        dismissed={dismissed}
        L={L}
        onUndo={undo}
        onHover={setBarHovered}
        ariaShortcut={toAriaKeyShortcuts("mod+z", platform)}
        className={viewAllHref ? "bottom-[4.25rem]" : "bottom-3"}
      />

      <span role="status" aria-live="polite" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}

/** One day of notifications. A labelled group, not a <section>: a landmark per day would flood the landmark list. */
export function DayGroup({ label, Heading, children }: { label: string; Heading: HeadingTag; children: ReactNode }) {
  const id = useId();
  return (
    <div role="group" aria-labelledby={id}>
      <Heading
        id={id}
        // Sticky over the scrolling rows: a near-opaque surface, with no blur of its own. It sits inside a
        // glass panel (already a backdrop root) and one blur per group header would blow the glass budget.
        className="sticky top-0 z-20 bg-sheen-surface/95 px-4 pt-3 pb-1.5 text-2xs font-semibold tracking-[0.12em] text-sheen-fg-subtle uppercase"
      >
        {label}
      </Heading>
      <ul className="flex flex-col pb-1">{children}</ul>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type MouseEvent, type PointerEvent, type ReactNode } from "react";
import {
  AnimatePresence,
  animate,
  motion,
  useDragControls,
  useIsPresent,
  useMotionValue,
  useMotionValueEvent,
  useTransform,
  type PanInfo,
} from "motion/react";

import { cn } from "../../lib/cn";
import { useSheenReducedMotion } from "../../hooks/use-preferences";
import { duration, ease, spring } from "../../motion/tokens";
import { Avatar } from "../../avatar/avatar";
import { Button } from "../../button/button";
import { KbdShortcut } from "../../kbd/kbd";
import { Tooltip } from "../../tooltip/tooltip";
import { type NotificationItem, type NotificationCenterLabels } from "./model";
import { Icon, CheckIcon, DotIcon, XIcon, TrashIcon, kindIcons, kindTone } from "./icons";
import { type Dismissed } from "./panel-body";

/* ---------- Row ---------- */

/** The props of one notification row. @internal */
export type RowProps = {
  item: NotificationItem;
  fresh: boolean;
  onSeen: () => void;
  /** "5m", "09:41"…; null when the item's time can't be read (nothing is shown). */
  time: string | null;
  fullTime?: string;
  dateTime?: string;
  L: NotificationCenterLabels;
  onSelect: (item: NotificationItem) => void;
  onToggleRead: (read: boolean) => void;
  onDismiss: (item: NotificationItem, moveFocus: boolean) => void;
};

/** Past this many px (or a quick flick), letting go dismisses. */
export const SWIPE_DISTANCE = 96;
/** The swipe speed, in pixels per second, that dismisses a row. @internal */
export const SWIPE_VELOCITY = 600;

/** One notification row with swipe-to-dismiss and hover actions. @internal */
export function NotificationRow({
  item,
  fresh,
  onSeen,
  time,
  fullTime,
  dateTime,
  L,
  onSelect,
  onToggleRead,
  onDismiss,
}: RowProps) {
  const reduced = useSheenReducedMotion();
  const isPresent = useIsPresent();
  const x = useMotionValue(0);
  const dragControls = useDragControls();
  const dragged = useRef(false);
  const [armed, setArmed] = useState(false);
  const iconScale = useTransform(x, [-SWIPE_DISTANCE - 24, -SWIPE_DISTANCE, -24], [1.2, 1.12, 0.85]);
  const descId = useId();
  const timeId = useId();

  // A one-off glow for rows that arrive while the panel is open.
  const [glow] = useState(fresh);
  useEffect(() => {
    if (fresh) onSeen();
  }, [fresh, onSeen]);

  useMotionValueEvent(x, "change", (value) => {
    const next = value <= -SWIPE_DISTANCE;
    if (next !== armed) {
      setArmed(next);
      // A light tick where supported (Android), so the threshold can be felt.
      if (next && "vibrate" in navigator) navigator.vibrate(8);
    }
  });

  function startDrag(event: PointerEvent<HTMLDivElement>) {
    // Swiping is for fingers. Mouse and pen keep text selection and the hover actions.
    if (event.pointerType !== "touch") return;
    dragged.current = false;
    dragControls.start(event);
  }

  function endDrag(_: unknown, info: PanInfo) {
    if (info.offset.x <= -SWIPE_DISTANCE || info.velocity.x <= -SWIPE_VELOCITY) {
      onDismiss(item, false);
      return;
    }
    animate(x, 0, reduced ? { duration: 0 } : spring.snappy);
  }

  function open(event: MouseEvent) {
    // The click that ends a swipe is not a tap.
    if (dragged.current) {
      event.preventDefault();
      dragged.current = false;
      return;
    }
    onSelect(item);
  }

  const describedBy = [item.description ? descId : null, time ? timeId : null].filter(Boolean).join(" ") || undefined;
  const mainClass = cn(
    "rounded-sheen-sm text-start outline-none",
    // Stretched over the whole row, so the row is one big target; the focus ring draws on that layer.
    "after:absolute after:inset-0 after:content-['']",
    "focus-visible:after:outline-2 focus-visible:after:-outline-offset-2 focus-visible:after:outline-sheen-focus",
  );
  const mainContent = (
    <>
      {item.title}
      {!item.read && <span className="sr-only">, {L.unreadState}</span>}
    </>
  );

  return (
    <motion.li
      layout={reduced ? false : "position"}
      transition={spring.snappy}
      initial={reduced ? false : { y: -10 }}
      animate={{ y: 0 }}
      data-notification-id={item.id}
      // While it leaves, the row is out of the tab order and ignores clicks.
      inert={!isPresent}
      // Scrolled into view clear of the sticky day heading, and of the undo bar while it shows.
      className="relative scroll-mt-10 overflow-hidden group-data-undo/inbox:scroll-mb-16"
    >
      {/* Swipe panel: sits just past the row's right edge and moves with it, so it never shows through the row. */}
      <motion.div
        aria-hidden
        style={{ x }}
        exit={{
          opacity: 0,
          transition: { duration: reduced ? 0 : duration.exit, ease: ease.exit, delay: reduced ? 0 : 0.16 },
        }}
        className="sheen-fill absolute inset-y-0 left-full flex w-full items-center gap-2 pl-5 text-sm font-semibold text-sheen-accent-fg [background-image:var(--sheen-danger-fill)] forced-colors:bg-[Mark] forced-colors:text-[MarkText]"
      >
        <motion.span style={{ scale: reduced ? 1 : iconScale }} className="flex">
          <TrashIcon className="size-5" />
        </motion.span>
        <span
          className={cn("transition-opacity duration-(--sheen-duration-fast)", armed ? "opacity-100" : "opacity-80")}
        >
          {L.swipeDismiss}
        </span>
      </motion.div>

      <motion.div
        style={{ x }}
        drag="x"
        dragListener={false}
        dragControls={dragControls}
        dragDirectionLock
        dragMomentum={false}
        dragConstraints={{ left: -10_000, right: 0 }}
        dragElastic={{ left: 0, right: 0.06 }}
        onPointerDown={startDrag}
        onDragStart={() => {
          dragged.current = true;
        }}
        onDragEnd={endDrag}
        exit={{ x: "-100%", transition: reduced ? { duration: 0 } : { duration: duration.base, ease: ease.exit } }}
        data-unread={item.read ? undefined : ""}
        className={cn(
          "group/row relative isolate flex touch-pan-y touch-pinch-zoom gap-3 px-4 py-3",
          "transition-colors duration-(--sheen-duration-fast) hover:bg-sheen-hover",
        )}
      >
        {/* Unread tint on its own layer: it fades (opacity) instead of repainting the row. */}
        <span
          aria-hidden
          className={cn(
            "pointer-events-none absolute inset-0 -z-10 bg-sheen-accent-soft transition-opacity duration-(--sheen-duration-base) ease-sheen-out",
            item.read ? "opacity-0" : "opacity-60",
          )}
        />
        {glow && !reduced && (
          <motion.span
            aria-hidden
            initial={{ opacity: 1 }}
            animate={{ opacity: 0 }}
            transition={{ duration: duration.slower * 3, ease: ease.out, delay: duration.slower }}
            className="pointer-events-none absolute inset-0 -z-10 bg-sheen-accent-soft shadow-[inset_3px_0_0_var(--sheen-accent)]"
          />
        )}

        <ItemAvatar item={item} />

        <div className="flex min-w-0 flex-1 flex-col">
          <p
            className={cn(
              "text-sm leading-snug [overflow-wrap:anywhere] [&_b]:font-semibold [&_b]:text-sheen-fg [&_strong]:font-semibold [&_strong]:text-sheen-fg",
              item.read ? "text-sheen-fg-muted" : "text-sheen-fg",
            )}
          >
            {item.href ? (
              <a
                href={item.href}
                data-slot="notification-main"
                aria-describedby={describedBy}
                aria-keyshortcuts="Delete"
                onClick={open}
                className={mainClass}
              >
                {mainContent}
              </a>
            ) : (
              <button
                type="button"
                data-slot="notification-main"
                aria-describedby={describedBy}
                aria-keyshortcuts="Delete"
                onClick={open}
                className={mainClass}
              >
                {mainContent}
              </button>
            )}
          </p>
          {item.description && (
            <p id={descId} className="mt-1 line-clamp-2 text-sm text-sheen-fg-muted [overflow-wrap:anywhere]">
              {item.description}
            </p>
          )}
          {item.actions && <div className="relative z-10 mt-2.5 flex flex-wrap gap-2">{item.actions}</div>}

          <div className="mt-1.5 flex min-h-7 items-center gap-2">
            {time && (
              <time
                id={timeId}
                dateTime={dateTime}
                title={fullTime}
                className="text-xs text-sheen-fg-muted tabular-nums"
              >
                {time}
              </time>
            )}
            <div
              className={cn(
                "relative z-10 ms-auto -me-1.5 flex items-center gap-0.5 any-pointer-coarse:gap-4",
                // Revealed on hover or focus with a mouse; always there on touch screens.
                "opacity-0 transition-opacity duration-(--sheen-duration-fast) group-hover/row:opacity-100 group-focus-within/row:opacity-100 any-pointer-coarse:opacity-100",
              )}
            >
              <RowAction label={item.read ? L.markUnread : L.markRead} onClick={() => onToggleRead(!item.read)}>
                {item.read ? <DotIcon /> : <CheckIcon />}
              </RowAction>
              <RowAction label={L.dismiss} onClick={() => onDismiss(item, true)}>
                <XIcon />
              </RowAction>
            </div>
          </div>
        </div>

        <span
          aria-hidden
          className={cn(
            "mt-1.5 size-2 shrink-0 rounded-full bg-sheen-accent shadow-[0_0_0_3px_var(--sheen-accent-soft)]",
            "transition-[opacity,scale] duration-(--sheen-duration-base) ease-sheen-out forced-colors:bg-[Highlight]",
            item.read ? "opacity-0 motion-ok:scale-50" : "opacity-100",
          )}
        />
      </motion.div>
    </motion.li>
  );
}

/** A small icon button in a notification row. @internal */
export function RowAction({ label, onClick, children }: { label: string; onClick: () => void; children: ReactNode }) {
  return (
    <Tooltip content={label} side="top" delay={500}>
      <Button
        variant="ghost"
        size="sm"
        aria-label={label}
        onClick={onClick}
        className="size-7 px-0 text-sheen-fg-muted hover:text-sheen-fg"
      >
        {children}
      </Button>
    </Tooltip>
  );
}

/** The avatar (or kind icon) of a notification. @internal */
export function ItemAvatar({ item }: { item: NotificationItem }) {
  const kind = item.kind ?? "system";
  if (!item.actor) {
    return (
      <span
        aria-hidden
        className={cn(
          "flex size-10 shrink-0 items-center justify-center rounded-full forced-colors:border forced-colors:border-[CanvasText]",
          kindTone[kind],
        )}
      >
        <Icon className="size-5">{kindIcons[kind]}</Icon>
      </span>
    );
  }
  return (
    <span className="relative h-fit shrink-0">
      <Avatar name={item.actor.name} src={item.actor.avatar} size="md" />
      {item.kind && (
        <span
          aria-hidden
          className={cn(
            "absolute -end-1 -bottom-1 flex size-5 items-center justify-center rounded-full ring-2 ring-sheen-surface forced-colors:border forced-colors:border-[CanvasText]",
            kindTone[item.kind],
          )}
        >
          <Icon className="size-3" strokeWidth="2.2">
            {kindIcons[item.kind]}
          </Icon>
        </span>
      )}
    </span>
  );
}

/** The bar that offers to undo the last dismissal. @internal */
export function UndoBar({
  dismissed,
  L,
  onUndo,
  onHover,
  ariaShortcut,
  className,
}: {
  dismissed: Dismissed | null;
  L: NotificationCenterLabels;
  onUndo: () => void;
  onHover: (hovered: boolean) => void;
  /** aria-keyshortcuts value of the undo shortcut. */
  ariaShortcut: string;
  className?: string;
}) {
  const reduced = useSheenReducedMotion();
  return (
    <AnimatePresence>
      {dismissed && (
        <motion.div
          key={dismissed.item.id}
          // Springs up; leaves quicker, without overshoot.
          initial={reduced ? { opacity: 0 } : { opacity: 0, y: 16, scale: 0.96 }}
          animate={{ opacity: 1, y: 0, scale: 1, transition: reduced ? { duration: duration.fast } : spring.snappy }}
          exit={{ opacity: 0, y: reduced ? 0 : 8, transition: { duration: duration.exit, ease: ease.exit } }}
          onPointerEnter={() => onHover(true)}
          onPointerLeave={() => onHover(false)}
          // A solid surface (not glass): it floats over rows, and text under frosted glass would show through.
          className={cn(
            "absolute inset-x-3 z-30 flex items-center justify-between gap-3 rounded-sheen-lg border border-sheen-border bg-sheen-surface py-1.5 ps-4 pe-1.5 text-sm",
            "shadow-[0_1px_2px_var(--sheen-shadow-near),0_12px_32px_-8px_var(--sheen-shadow-far)] forced-colors:border-[CanvasText]",
            className,
          )}
        >
          <span className="min-w-0 truncate text-sheen-fg-muted">{L.dismissed}</span>
          <Button
            variant="ghost"
            size="sm"
            onClick={onUndo}
            aria-keyshortcuts={ariaShortcut}
            className="text-sheen-accent"
          >
            {L.undo}
            {/* The shortcut, for keyboards (hidden on touch-only screens). */}
            <KbdShortcut keys="mod+z" announce={false} className="hidden pointer-fine:inline-flex" />
          </Button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { useControllable } from "../../hooks/use-controllable";

import { type NotificationItem, type NotificationCenterLabels } from "./model";

/* ---------- Dates ---------- */

/** One day in milliseconds. @internal */
export const DAY = 86_400_000;

/** The item's time as a Date, or null when it can't be read (one bad API value must not break the inbox). */
export function toDate(time: NotificationItem["time"]): Date | null {
  const date = time instanceof Date ? time : new Date(time);
  return Number.isNaN(date.getTime()) ? null : date;
}

/** Newest first; undated items last, in their original order. */
export function byNewest(dates: Map<string, Date | null>) {
  return (a: NotificationItem, b: NotificationItem) => {
    const ta = dates.get(a.id)?.getTime();
    const tb = dates.get(b.id)?.getTime();
    if (ta === undefined || tb === undefined) return ta === tb ? 0 : ta === undefined ? 1 : -1;
    return tb - ta;
  };
}

/** The local midnight of a date. @internal */
export function startOfDay(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
}

/** Whole calendar days between `date` and `now` (0 = today). Rounded, so DST shifts don't matter. */
export function daysAgo(date: Date, now: Date) {
  return Math.round((startOfDay(now) - startOfDay(date)) / DAY);
}

/** Builds the memoised date and number formatters of a locale. @internal */
export function useFormatters(locale: string | undefined) {
  return useMemo(
    () => ({
      relative: new Intl.RelativeTimeFormat(locale, { numeric: "always", style: "narrow" }),
      weekday: new Intl.DateTimeFormat(locale, { weekday: "long" }),
      day: new Intl.DateTimeFormat(locale, { month: "long", day: "numeric" }),
      dayYear: new Intl.DateTimeFormat(locale, { month: "long", day: "numeric", year: "numeric" }),
      clock: new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit" }),
      full: new Intl.DateTimeFormat(locale, { dateStyle: "full", timeStyle: "short" }),
    }),
    [locale],
  );
}

/** The formatter set that `useFormatters` returns. @internal */
export type Formatters = ReturnType<typeof useFormatters>;

/** The group heading of a date: Today, Yesterday, a weekday or a full date. @internal */
export function groupLabel(date: Date | null, now: Date, f: Formatters, L: NotificationCenterLabels) {
  if (!date) return L.undated;
  const days = daysAgo(date, now);
  if (days <= 0) return L.today;
  if (days === 1) return L.yesterday;
  if (days < 7) return f.weekday.format(date);
  return (date.getFullYear() === now.getFullYear() ? f.day : f.dayYear).format(date);
}

/** The relative or absolute timestamp text of a notification. @internal */
export function timeLabel(date: Date, now: Date, f: Formatters, L: NotificationCenterLabels) {
  if (daysAgo(date, now) > 0) return f.clock.format(date);
  const seconds = (now.getTime() - date.getTime()) / 1000;
  if (seconds < 60) return L.justNow;
  if (seconds < 3600) return f.relative.format(-Math.floor(seconds / 60), "minute");
  return f.relative.format(-Math.floor(seconds / 3600), "hour");
}

/**
 * Turns the blur of glass nested inside `root` off (true) or back on (false): .glass-* and
 * anything marked data-sheen-blur. A fading element must never contain a backdrop-filter, so
 * this runs while the panel around them fades.
 */
export function settleNestedGlass(root: HTMLElement | null, on: boolean) {
  root?.querySelectorAll<HTMLElement>(".glass-1, .glass-2, .glass-3, [data-sheen-blur]").forEach((el) => {
    if (on) {
      el.style.setProperty("backdrop-filter", "none");
      el.style.setProperty("-webkit-backdrop-filter", "none");
    } else {
      el.style.removeProperty("backdrop-filter");
      el.style.removeProperty("-webkit-backdrop-filter");
    }
  });
}

/** The current time, refreshed every 30s so "5m ago" keeps up. A `fixed` time (prerendering, tests) is used as is. */
export function useNow(fixed?: Date) {
  const [now, setNow] = useState(() => new Date());
  const fixedTime = fixed?.getTime();
  useEffect(() => {
    if (fixedTime !== undefined) return;
    const timer = window.setInterval(() => setNow(new Date()), 30_000);
    return () => window.clearInterval(timer);
  }, [fixedTime]);
  return useMemo(() => (fixedTime === undefined ? now : new Date(fixedTime)), [fixedTime, now]);
}

/* ---------- State ---------- */

/** A state updater that takes the previous notification list and returns the next. @internal */
export type Update = (fn: (previous: NotificationItem[]) => NotificationItem[]) => void;
/** A stable empty notification list, so a default never changes identity. @internal */
export const NO_NOTIFICATIONS: NotificationItem[] = [];

/** Controlled or uncontrolled list, with functional updates that never read a stale list. */
export function useNotificationList(
  value: NotificationItem[] | undefined,
  defaultValue: NotificationItem[] | undefined,
  onChange?: (next: NotificationItem[]) => void,
) {
  const [items, update] = useControllable<NotificationItem[]>(value, defaultValue ?? NO_NOTIFICATIONS, onChange);
  return [items, update as Update] as const;
}

/** True when a notification mentions the user. @internal */
export const isMention = (item: NotificationItem) => item.mention ?? item.kind === "mention";

